function sliderServices() {
    var swiper = new Swiper('.services .mySwiper', {
        slidesPerView: 1,
        spaceBetween: 20,
        speed: 1200,
        navigation: {
            nextEl: ".services .swiper-button-next",
            prevEl: ".services .swiper-button-prev",
        },
        breakpoints: {
            320: {
                spaceBetween: 10,
            },
            993: {
                spaceBetween: 20,
            },
        }
    });
}

function planGallery() {
    let SlidersArray = []

    let sliders = document.querySelectorAll(".plan__images")
    sliders.forEach((slider, index) => {
        slider.setAttribute("data-slider-id", index)
        let gallery = {
            mySwiper: {},
            mySwiper2: {}
        }

        gallery.mySwiper = new Swiper(`.plan__images[data-slider-id="${index}"] .mySwiper`, {
            slidesPerView: 4,
            spaceBetween: 16,
            freeMode: true,
        });

        gallery.mySwiper2 = new Swiper(`.plan__images[data-slider-id="${index}"] .mySwiper2`, {
            spaceBetween: 16,
            slidesPerView: 1,
            navigation: {
                nextEl: `.plan__images[data-slider-id="${index}"] .swiper-button-next`,
                prevEl: `.plan__images[data-slider-id="${index}"] .swiper-button-prev`,
            },
            thumbs: {
                swiper: gallery.mySwiper,
            },
        });

        SlidersArray[index] = gallery
    })
}

function sliderPlanMob() {
    var swiper = new Swiper('.plan-mob .mySwiper', {
        slidesPerView: 1,
        spaceBetween: 20,
        effect: "fade",
        direction: "vertical",
    });

    let atLastSlide = false;

    swiper.on('slideChange', function () {
        atLastSlide = swiper.isEnd;
    });

    swiper.on('touchEnd', function () {
        if (atLastSlide && swiper.touches.diff < 0) {
            const planMobElem = document.querySelector('.plan-mob');
            if (planMobElem) {
                planMobElem.remove();
            }
        }
    });
}

function sliderAboutAdvantages() {
	var swiper = new Swiper('.about-advantages .mySwiper', {
		slidesPerView: 3,
		spaceBetween: 20,
		allowTouchMove: false,
		simulateTouch: false,
		touchRatio: 0,
		breakpoints: {
			320: {
				slidesPerView: 1.2,
                spaceBetween: 10,
                allowTouchMove: true,
                simulateTouch: true,
                touchRatio: 1,
			},
			451: {
				slidesPerView: 2,
                spaceBetween: 10,
                allowTouchMove: true,
                simulateTouch: true,
                touchRatio: 1,
			},
			769: {
				slidesPerView: 2.5,
                spaceBetween: 10,
                allowTouchMove: true,
                simulateTouch: true,
                touchRatio: 1,
			},
			993: {
				slidesPerView: 3,
                spaceBetween: 20,
                allowTouchMove: false,
		        simulateTouch: false,
		        touchRatio: 0,
			},
		}
	});
}

$(document).ready(function () {
    sliderServices();
    planGallery();
    sliderPlanMob();
    sliderAboutAdvantages();

    // Menu
    $('.burger').click(function () {
        $(this).toggleClass('burger--active')
        $('.menu').toggleClass('menu--active')
        $('body').toggleClass('fixed-body')
    })

    // Btn-animation
    $(".btn-animation").mouseenter(function(e) {
        var $this = $(this);
        var $animation = $this.find(".circle");
        var offset = $this.offset();
        var x = e.pageX - offset.left;
        var y = e.pageY - offset.top;
        $animation.css({
            top: y + 'px',
            left: x + 'px'
        });
    });

    $(".btn-animation").mousemove(function(e) {
        var $this = $(this);
        var $animation = $this.find(".circle");
        var offset = $this.offset();
        var x = e.pageX - offset.left;
        var y = e.pageY - offset.top;
        $animation.css({
            top: y + 'px',
            left: x + 'px'
        });
    });

    // Form
    let isClicked = false;
    $('.form').on('submit', function(e) {
        e.preventDefault();

        isClicked = true;
        let allFilled = true;

        $(this).find('.form-group input').each(function() {
            const $input = $(this);
            const $formGroup = $input.closest('.form-group');

            if ($input.val().trim() === '') {
                $formGroup.addClass('form-group--active');
                allFilled = false;
            } else {
                $formGroup.removeClass('form-group--active');
            }
        });
    });
    $('.form-group input').on('input', function() {
        if (isClicked) {
            const $input = $(this);
            const $formGroup = $input.closest('.form-group');

            if ($input.val().trim() === '') {
                $formGroup.addClass('form-group--active');
            } else {
                $formGroup.removeClass('form-group--active');
            }
        }
    });

    // Up
    var t = $(".up");

    $(window).scroll(function() {
        if ($(window).scrollTop() > 300) {
            t.addClass("up--active");
        } else {
            t.removeClass("up--active");
        }
    });

    t.on("click", function(e) {
        e.preventDefault();
        $("html, body").animate({
            scrollTop: 0
        }, 300);
    });

    // Modal
    $("[data-modal]").click(function () {
        let modalId = $(this).attr("data-modal")

        openModal(modalId)
    })

    function openModal(modalId){
        $(`#${modalId}`).addClass("modal--active")
        $("body").addClass("fixed-body2")
    }

    $(".modal").click(function () {
        closeModal()
    })

    $("._close-modal").click(function () {
        closeModal()
    })

    $(".modal__dialog").click(function (e) {
        e.stopPropagation()
    })

    function closeModal() {
        $('.modal--active video').each(function () {
            this.pause();
            this.currentTime = 0;
        });
        
        $('.modal').removeClass("modal--active")
        $("body").removeClass("fixed-body2")
    }

    // Cookies
    $('.cookies__btn').click(function () {
        $(this).parents('.cookies').remove()
    })

    $('.cookies__close').click(function () {
        $(this).parents('.cookies').remove()
    })

    // hover slider
    $(".hover__pag-item").mouseover(function() {
        let path = $(this).attr("data-tab-path")
        $(this).parents(".hover__slide").find(".hover__pag-item").removeClass("hover__pag-item--active")
        $(this).addClass("hover__pag-item--active")
        $(this).parents(".hover__slide").find(".hover__img").removeClass("hover__img--active")
        $(this).parents(`.hover__slide`).find(`.hover__img[data-tab-path="${path}"]`).addClass("hover__img--active")
        $(this).parents(".hover__slide").find(".pagination-bullet").removeClass("pagination-bullet--active")
        $(this).parents(`.hover__slide`).find(`.pagination-bullet[data-tab-path="${path}"]`).addClass("pagination-bullet--active")
    })


});








